//! Takács 10-layer parity against `src/sim/takacs.ts`.
//!
//! Fixture: BSM1 settler, area 1500 m2, depth 4 m, 10 layers, feed layer 5,
//! feed 18446 m3/d at 3000 g/m3, underflow 3850 m3/d, 24 x 1 h steps.
//! Golden profile generated by the TypeScript oracle on 2026-11-25.

use aquapilot_core::takacs::{
    BSM1_SETTLER, SettlerFeed, SettlerUnderflow, create_settler, step_settler,
};

const PROFILE: [f64; 10] = [
    10.233612496414231,
    14.345010939541295,
    22.431418892868795,
    48.68570561938496,
    222.37930336989305,
    222.37930336989305,
    222.37930336989305,
    294.1121227698668,
    221.66762363285974,
    14348.88877729825,
];

#[test]
fn takacs_24h_matches_ts_golden() {
    let mut state = create_settler(&BSM1_SETTLER, 3000.0);
    let mut last = None;
    for _ in 0..24 {
        let out = step_settler(
            &state,
            &BSM1_SETTLER,
            SettlerFeed {
                flow: 18446.0,
                concentration: 3000.0,
            },
            SettlerUnderflow { flow: 3850.0 },
            1.0 / 24.0,
        );
        state = out.state.clone();
        last = Some(out);
    }
    let last = last.expect("24 steps");
    for (i, want) in PROFILE.iter().enumerate() {
        let got = state.x[i];
        // The bottom layer is ~14,000 g/m3; allow 64 f64 ulps for the
        // TypeScript/Rust transcendental difference, not a model tolerance.
        let tol = 64.0 * f64::EPSILON * want.abs().max(1.0);
        assert!(
            (got - want).abs() <= tol,
            "layer {i}: got {got} want {want} tol {tol}"
        );
    }
    assert!((last.x_effluent - PROFILE[0]).abs() <= 1e-12);
    let underflow_tol = 64.0 * f64::EPSILON * PROFILE[9].abs();
    assert!((last.x_underflow - PROFILE[9]).abs() <= underflow_tol);
    assert!((last.solids_loading - 1.5371666666666666).abs() <= 1e-12);
}
